import 'dart:convert';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';
import 'app_config.dart';
class DashboardService{Future<Map<String,dynamic>>_get(String path)async{final p=await SharedPreferences.getInstance();final token=p.getString('accessToken');final r=await http.get(Uri.parse('${AppConfig.apiBaseUrl}$path'),headers:{'Authorization':'Bearer $token','Accept':'application/json'});final d=jsonDecode(r.body.isEmpty?'{}':r.body)as Map<String,dynamic>;if(r.statusCode<200||r.statusCode>=300)throw Exception(d['error']??'Unable to load data');return d;}Future<Map<String,dynamic>>parentOverview()=>_get('/api/portal/me/overview');Future<Map<String,dynamic>>notifications()=>_get('/api/notifications/me?limit=20');Future<Map<String,dynamic>>students()=>_get('/api/portal/me/students');Future<Map<String,dynamic>>teacherOverview()=>_get('/api/portal/me/teacher-overview');Future<Map<String,dynamic>>adminOverview()=>_get('/api/portal/me/admin-overview');Future<Map<String,dynamic>>studentOverview()=>_get('/api/portal/me/student-overview');Future<Map<String,dynamic>>driverOverview()=>_get('/api/transport/driver/overview');Future<Map<String,dynamic>>startTrip(String id)async=>_post('/api/transport/trips/$id/start',{});Future<Map<String,dynamic>>completeTrip(String id)async=>_post('/api/transport/trips/$id/complete',{});Future<Map<String,dynamic>>event(String id,String studentId,String type,{String?stopId})async=>_post('/api/transport/trips/$id/events',{'studentId':studentId,'eventType':type,'stopId':stopId});Future<Map<String,dynamic>>_post(String path,Map<String,dynamic>body)async{final p=await SharedPreferences.getInstance();final r=await http.post(Uri.parse('${AppConfig.apiBaseUrl}$path'),headers:{'Authorization':'Bearer ${p.getString('accessToken')}','Content-Type':'application/json'},body:jsonEncode(body));final d=jsonDecode(r.body.isEmpty?'{}':r.body)as Map<String,dynamic>;if(r.statusCode<200||r.statusCode>=300)throw Exception(d['error']??'Request failed');return d;}}
